"""Disposable SQL-only comparison; no PA boot or live files."""
import hashlib,json,os,sqlite3,tempfile,time
from pathlib import Path
with tempfile.TemporaryDirectory(prefix='pa-startup-json-reparse-') as tmp:
 os.environ['PA_DATA_DIR']=str(Path(tmp)/'data');os.environ['PA_WORKSPACE_ROOT']=str(Path(tmp)/'workspaces')
 from pa.domain.projection import _STARTUP_CONFIG_JSON
 from pa.core.performance import distribution
 conn=sqlite3.connect(':memory:');conn.execute('CREATE TABLE fixture(id INTEGER,config_json TEXT)')
 normal=json.dumps({'configuration':{'effective':{'model_id':'fixture'}},'durable_runtime':{'queued_prompts':[{'id':'synthetic','message':'fixture'}]},'provisioning':{'action':'retained'},'execution_selection':{'proof':'x'*131072},'future_extension':'y'*131072})
 cases=['{}','null','[]','3','false','"fixture"','[invalid','{"configuration":{"first":1},"configuration":{"last":2}}','{"durable_runtime":false}','{"provisioning":3}','{"configuration":[],"durable_runtime":[],"provisioning":[]}']
 conn.executemany('INSERT INTO fixture VALUES(?,?)',enumerate([normal]*160+cases));conn.commit()
 baseline='SELECT id,'+_STARTUP_CONFIG_JSON+' AS config_json FROM fixture ORDER BY id'
 binary=_STARTUP_CONFIG_JSON.replace('json_valid(config_json)','binary IS NOT NULL').replace('json_type(config_json','json_type(binary').replace('json_each(config_json)','json_each(binary)').replace('json_extract(config_json','json_extract(binary')
 candidates={'materialized':'WITH parsed AS MATERIALIZED (SELECT id,config_json,CASE WHEN json_valid(config_json) THEN jsonb(config_json) END AS binary FROM fixture) SELECT id,'+binary+' AS config_json FROM parsed ORDER BY id','binary_functions':baseline.replace('json_type(config_json','json_type(jsonb(config_json)').replace('json_each(config_json)','json_each(jsonb(config_json))').replace('json_extract(config_json','json_extract(jsonb(config_json)')}
 expected=conn.execute(baseline).fetchall();assert len(expected)==171
 out={'scope':'160 synthetic256KiBconfigs plus11legacy edgecases in memory;20 alternating pairs percandidate, exactrawSQLresults checked. No PA runtime, ownerdata, workload or deployment. SQLCPU/memory only, not proof of historical1196msstartup cause.','sqlite':sqlite3.sqlite_version,'pairs':{},'bytes':sum(len(v[1]) for v in conn.execute('SELECT * FROM fixture'))}
 for name,query in candidates.items():
  values={'baseline':[],'candidate':[]}
  for i in range(20):
   for label,sql in ([('baseline',baseline),('candidate',query)] if i%2==0 else [('candidate',query),('baseline',baseline)]):
    start=time.perf_counter();rows=conn.execute(sql).fetchall();elapsed=(time.perf_counter()-start)*1000;assert rows==expected;values[label].append(elapsed)
  out['pairs'][name]={'samples':values,'distribution':{k:distribution(v) for k,v in values.items()},'query':query,'exact_rows_equal':True}
 p=Path('.dev/startup-sql-reparse-probe.json');assert not p.exists();p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'output':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'sqlite':out['sqlite'],'pairs':{k:v['distribution'] for k,v in out['pairs'].items()}}))
